  /* ---------- surname banners ---------- */
  function bannerTex(text,col){
    return canvasTex(128,384,function(x,w,h){
      x.fillStyle=col;x.fillRect(0,0,w,h);
      const g=x.createLinearGradient(0,0,0,h);g.addColorStop(0,'rgba(255,255,255,.16)');g.addColorStop(1,'rgba(0,0,0,.28)');x.fillStyle=g;x.fillRect(0,0,w,h);
      x.strokeStyle='#e6c068';x.lineWidth=7;x.strokeRect(8,8,w-16,h-16);x.lineWidth=2;x.strokeRect(20,20,w-40,h-40);
      const ch=Array.from(text);x.fillStyle='#fbf0d0';x.textAlign='center';x.textBaseline='middle';
      x.shadowColor='rgba(0,0,0,.55)';x.shadowBlur=8;
      const fam="'Yuji Syuku','Hiragino Mincho ProN','Yu Mincho',serif";
      if(ch.length===1){x.font='150px '+fam;x.fillText(ch[0],w/2,h*.5);}
      else{x.font='104px '+fam;x.fillText(ch[0],w/2,h*.36);x.fillText(ch[1],w/2,h*.66);}
    });
  }
  G3.setBanners=function(me,foe){
    banners.forEach(function(b){
      const h=b.side?foe:me,tex=bannerTex(surname(h),b.side?'#a8322a':'#245f9e');
      if(b.mat.map)b.mat.map.dispose();b.mat.map=tex;b.mat.needsUpdate=true;
    });
  };
